<?php
/**
 * PRISM consistent module starter.
 * Copy this file into the relevant M#_Manage... folder, then replace the
 * placeholder section with that module's own database queries and actions.
 * The navigation, page header, user identity, cards and responsive table
 * classes below match the inventory and dashboards.
 */
declare(strict_types=1);
require_once __DIR__.'/../config.php';
function module_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$user=$_SESSION['inventory_user']??null;if(!$user){header('Location: ../login.php');exit;}
$modules=['users'=>['Team members','USER MANAGEMENT','♙'],'suppliers'=>['Suppliers','SUPPLIER DIRECTORY','◉'],'repairs'=>['Repair jobs','SERVICE WORKSHOP','⚒']];$key=(string)($_GET['module']??'repairs');if(!isset($modules[$key]))$key='repairs';[$title,$eyebrow,$icon]=$modules[$key];$role=strtolower($user['role']);$roleKey=in_array($role,['shop admin','admin'],true)?'admin':(in_array($role,['technician','tech'],true)?'technician':'salesperson');$isAdmin=$roleKey==='admin';if($key==='users'&&!$isAdmin){http_response_code(403);exit('Shop Admin access required.');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=module_h($title)?> · PRISM</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@700&display=swap" rel="stylesheet"><link rel="stylesheet" href="../css/prism.css"></head><body><div class="shell"><aside class="side"><a class="brand" href="module_template.php?module=repairs"><span class="mark">P</span><span>PRISM</span></a><div class="workspace"><span>WORKSPACE</span><b><?=module_h($user['role'])?></b></div><nav class="nav-list"><a class="nav" href="M1_ManageUser/<?=module_h($roleKey)?>_dashboard.php"><span class="nav-icon">⌂</span>Overview</a><a class="nav" href="M2_ManageInventory/<?=module_h($roleKey)?>_inventory.php"><span class="nav-icon">▦</span>Inventory</a><?php if($isAdmin):?><a class="nav <?=($key==='users'?'active':'') ?>" href="module_template.php?module=users"><span class="nav-icon">♙</span>Users</a><a class="nav <?=($key==='suppliers'?'active':'') ?>" href="module_template.php?module=suppliers"><span class="nav-icon">◉</span>Suppliers</a><?php endif?><a class="nav <?=($key==='repairs'?'active':'') ?>" href="module_template.php?module=repairs"><span class="nav-icon">⚒</span>Repair jobs</a></nav><a class="nav signout" href="../login.php?logout=1">↗ Sign out</a><div class="side-foot">PHONE REPAIR<br>INVENTORY MANAGEMENT</div></aside><main class="main"><header class="top"><div><p class="eyebrow"><?=module_h($eyebrow)?></p><h1><?=module_h($title)?></h1></div><div class="top-user"><span class="today"><?=date('D, d M Y')?></span><span class="avatar"><?=module_h(strtoupper(substr($user['name'],0,1)))?></span><span class="user-label"><b><?=module_h($user['name'])?></b><small><?=module_h($user['role'])?></small></span></div></header><div class="welcome"><div><span class="promo-tag">MODULE STARTER</span><h2>Consistent PRISM page layout</h2><p>This template is ready for the module owner to add their database table, form actions, filters, and page content.</p></div></div><section class="stats"><article class="stat-card violet"><span class="stat-icon"><?=$icon?></span><span>Module</span><strong><?=module_h($title)?></strong><small><?=module_h($eyebrow)?></small></article><article class="stat-card teal"><span class="stat-icon">✓</span><span>Signed in as</span><strong><?=module_h($user['name'])?></strong><small><?=module_h($user['role'])?></small></article></section><section class="card"><div class="section-head"><div><span class="eyebrow">PAGE CONTENT</span><h2>Replace this area with your module</h2></div><?php if($isAdmin&&$key!=='repairs'):?><button type="button" class="btn primary">＋ Add <?=module_h(rtrim($title,'s'))?></button><?php endif?></div><div class="table-wrap"><table><thead><tr><?php foreach(($key==='users'?['Name','Username','Email','Role','Status','Actions']:($key==='suppliers'?['Supplier','Contact person','Email','Address','Status','Actions']:['Job','Customer','Device','Complaint','Status','Actions'])) as $col):?><th><?=module_h($col)?></th><?php endforeach?></tr></thead><tbody><tr><td colspan="6" class="empty-row">The assigned team member can replace this sample row with records from the existing prism database.</td></tr></tbody></table></div></section></main></div></body></html>